// levelBadge maps a log level to a badge variant.
func levelBadge(l logs.Level) badge.Variant {
	switch l {
	case logs.Error:
		return badge.Danger
	case logs.Warn:
		return badge.Warning
	case logs.Info:
		return badge.Info
	default: // Debug
		return badge.Secondary
	}
}

